<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{DeliveryException,DeliveryOrder,DeliveryOrderItem,InventoryBalance,ProofOfDeliveryRecord,SalesOrder,SalesOrderItem,ShipmentTrackingEvent,StockReservation};
use App\Services\{AuthorizationService,SalesNumberService,StockMovementService}; use App\Support\{Decimal,TenantContext}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class DeliveryOrderController {
 private function t():string{return app(TenantContext::class)->id();} private function own(Request $r,DeliveryOrder $s):void{abort_unless($s->tenant_id===$this->t(),404);abort_unless(app(AuthorizationService::class)->allows($r->user(),$this->t(),'sales.manage',$s->company_id,$s->branch_id),403);}
 public function show(Request $r,DeliveryOrder $shipment){$this->own($r,$shipment);return response()->json(['data'=>$shipment->load(['items','fulfillment.lines.orderItem.variant','trackingEvents','pod','exceptions'])]);}
 public function store(Request $r,SalesOrder $order,AuthorizationService $a,SalesNumberService $numbers){abort_unless($order->tenant_id===$this->t(),404);abort_unless($a->allows($r,$this->t(),'sales.manage',$order->company_id,$order->branch_id),403);$d=$r->validate(['idempotency_key'=>'required|string|max:100','items'=>'required|array|min:1','items.*.sales_order_item_id'=>'required|uuid','items.*.quantity'=>'required|numeric|gt:0']);$existing=DeliveryOrder::where('tenant_id',$this->t())->where('idempotency_key',$d['idempotency_key'])->first();if($existing)return response()->json(['data'=>$existing]);$s=DB::transaction(function()use($d,$order,$r,$numbers){$s=DeliveryOrder::create(['tenant_id'=>$order->tenant_id,'company_id'=>$order->company_id,'branch_id'=>$order->branch_id,'sales_order_id'=>$order->id,'created_by'=>$r->user()->id,'number'=>$numbers->next($order->tenant_id,'delivery'),'idempotency_key'=>$d['idempotency_key'],'shipment_status'=>'draft','state'=>'draft']);foreach($d['items'] as $line){$i=SalesOrderItem::where('tenant_id',$order->tenant_id)->where('sales_order_id',$order->id)->whereKey($line['sales_order_item_id'])->firstOrFail();$s->items()->create(['tenant_id'=>$order->tenant_id,'sales_order_item_id'=>$i->id,'location_id'=>$i->preferred_location_id,'quantity'=>$line['quantity']]);}return $s;});return response()->json(['data'=>$s->load('items')],201);}
 public function dispatch(Request $r,DeliveryOrder $shipment){$this->own($r,$shipment);$d=$r->validate(['idempotency_key'=>'required|string|max:100']);$out=DB::transaction(function()use($r,$shipment,$d){$s=DeliveryOrder::whereKey($shipment->id)->lockForUpdate()->firstOrFail();if($s->shipment_status==='dispatched')return $s;if($s->shipment_status!=='draft')throw ValidationException::withMessages(['status'=>['Shipment is not ready for dispatch.']]);$order=SalesOrder::whereKey($s->sales_order_id)->lockForUpdate()->firstOrFail();foreach($s->items()->lockForUpdate()->get() as $line){$item=SalesOrderItem::whereKey($line->sales_order_item_id)->lockForUpdate()->firstOrFail();$reservation=StockReservation::where('tenant_id',$s->tenant_id)->where('sales_order_item_id',$item->id)->where('state','active')->where('location_id',$line->location_id)->lockForUpdate()->firstOrFail();$qty=Decimal::normalize((string)$line->quantity);$remaining=Decimal::sub((string)$reservation->quantity,'0');if(Decimal::compare($qty,$remaining)>0)throw ValidationException::withMessages(['quantity'=>['Shipment exceeds active reservation.']]);$balance=InventoryBalance::where('tenant_id',$s->tenant_id)->where('variant_id',$item->variant_id)->where('location_id',$line->location_id)->lockForUpdate()->firstOrFail();$balance->update(['reserved_quantity'=>Decimal::sub((string)$balance->reserved_quantity,$qty)]);app(StockMovementService::class)->post(['tenant_id'=>$s->tenant_id,'variant_id'=>$item->variant_id,'location_id'=>$line->location_id,'quantity'=>Decimal::sub('0',$qty),'created_by'=>$r->user()->id,'movement_type'=>'sale_delivery','unit_cost'=>'0','reference_type'=>'delivery_order','reference_id'=>$s->id,'idempotency_key'=>'dispatch:'.$s->id.':'.$item->id]);$item->update(['delivered_quantity'=>Decimal::add((string)$item->delivered_quantity,$qty)]);$reservation->update(['quantity'=>Decimal::sub((string)$reservation->quantity,$qty),'state'=>Decimal::compare(Decimal::sub((string)$reservation->quantity,$qty),'0')===0?'consumed':'active']);if($s->fulfillment_id){$fl=$s->fulfillment?->lines()->where('sales_order_item_id',$item->id)->lockForUpdate()->first();if($fl)$fl->update(['dispatched_quantity'=>Decimal::add((string)$fl->dispatched_quantity,$qty)]);}}$s->update(['shipment_status'=>'dispatched','state'=>'posted','posted_at'=>now(),'dispatched_at'=>now(),'dispatched_by'=>$r->user()->id]);$complete=$order->items()->get()->every(fn($i)=>Decimal::compare((string)$i->delivered_quantity,(string)$i->ordered_quantity)>=0);$order->update(['state'=>$complete?'fulfilled':'partially_fulfilled']);return $s;});return response()->json(['data'=>$out->load('items')]);}
 public function tracking(Request $r,DeliveryOrder $shipment){$this->own($r,$shipment);$d=$r->validate(['status'=>'required|in:shipment_created,ready_for_dispatch,dispatched,in_transit,out_for_delivery,delivered,delivery_attempt_failed,return_to_sender,lost_exception','occurred_at'=>'nullable|date','external_reference'=>'nullable|string|max:150','notes'=>'nullable|string']);$event=ShipmentTrackingEvent::firstOrCreate(['tenant_id'=>$this->t(),'delivery_order_id'=>$shipment->id,'external_reference'=>$d['external_reference']??null],['status'=>$d['status'],'occurred_at'=>$d['occurred_at']??now(),'notes'=>$d['notes']??null,'recorded_by'=>$r->user()->id]);$shipment->update(['shipment_status'=>$d['status']]);return response()->json(['data'=>$event->fresh()]);}
 public function pod(Request $r,DeliveryOrder $shipment){$this->own($r,$shipment);abort_unless($shipment->shipment_status==='delivered'||$shipment->shipment_status==='out_for_delivery',422);$d=$r->validate(['delivered_at'=>'required|date','received_by'=>'nullable|string|max:150','delivery_location'=>'nullable|string','delivery_notes'=>'nullable|string','verification_method'=>'required|in:internal,carrier,signature,photo']);$pod=ProofOfDeliveryRecord::updateOrCreate(['delivery_order_id'=>$shipment->id],['tenant_id'=>$this->t(),'status'=>'verified','delivered_at'=>$d['delivered_at'],'received_by'=>$d['received_by']??null,'delivery_location'=>$d['delivery_location']??null,'delivery_notes'=>$d['delivery_notes']??null,'verification_method'=>$d['verification_method'],'recorded_by'=>$r->user()->id]);$shipment->update(['shipment_status'=>'delivered']);return response()->json(['data'=>$pod]);}
 public function exception(Request $r,DeliveryOrder $shipment){$this->own($r,$shipment);$d=$r->validate(['reason'=>'required|in:recipient_unavailable,incorrect_address,delivery_refused,damaged_in_transit,lost,delayed,return_to_sender','attempted_at'=>'required|date','notes'=>'nullable|string']);$e=DeliveryException::create(['tenant_id'=>$this->t(),'delivery_order_id'=>$shipment->id,'reason'=>$d['reason'],'attempted_at'=>$d['attempted_at'],'notes'=>$d['notes']??null,'recorded_by'=>$r->user()->id]);$shipment->update(['shipment_status'=>'delivery_exception']);return response()->json(['data'=>$e],201);}
}
